#!/usr/local/bin/prhm-node
'use strict';
const fs=require('node:fs');
const path=require('node:path');
const os=require('node:os');
const crypto=require('node:crypto');
const cp=require('node:child_process');
const http=require('node:http');

const VERSION='1.14.1-honartik-iticket-v14-preflight-readonly';
const TOOL='honartik_iticket_v14_preflight_readonly';
const V14_SHA='c7bce25d4d2c6a1274a3829dde4c7f5704868417c94bd24cd71feb5a3522b31b';
const ROUTE_SHA='a2c3480018f7e8cfb69eeda9cb92e122735f0694ecae3d7e69bd37b8124b5189';
const MCP_PLUGIN_SHA='963529d9ebec49e64ea98798ca0dbf2cd8542f4fb648213a05cb3351f83d28a2';
const IMMUTABLE_HOST_ACTIONS_V2_SHA='7efeeb17253bc52aeac1f362c377fd4121984f49f159fd9e72ae7e06897ded56';
const PATHS=Object.freeze({
  agentServer:'/home/agent/ssh-agent-api/server.js',
  agentRoute:'/home/agent/ssh-agent-api/honartikIticketV14PreflightRoutes.js',
  mcpRegistry:'/home/agent/ssh-mcp-server/src/core/registry.js',
  mcpPlugin:'/home/agent/ssh-mcp-server/src/plugins/honartikIticketPreflight.js',
  hostActionsV2:'/home/agent/ssh-mcp-server/src/plugins/hostActionsV2.js',
  payload:'/opt/prhm-agent-readonly-actions/honartik-iticket-v14-preflight.js',
  marker:'/var/lib/prhm-host-actions/honartik-iticket-v14-preflight-readonly-v1.json'
});
const EXPECTED=Object.freeze({
  agentServer:'70368fdc8be24646b10d414f6159502c2f3d338ed1132451d5b5740d1270999c',
  registry:'cf3681ca4d4632156df2f77886afe59c07da9a86dbcb68f4217577f811b22231'
});
const SERVICES=Object.freeze(['prhm-agent-api.service','prhm-agent-mcp.service']);
const V14_B64='';
const ROUTE_B64='';
const MCP_PLUGIN_B64='';
const AGENT_PATCH_ANCHOR=`source=replaceOnce(source,"'status'=>1,'created_at'=>$now","'status'=>2,'created_at'=>$now",'admin_active_status');`;
const AGENT_IMPORT_ANCHOR="const baseImotionMonitor=require('./imotionMonitorRoutes.js');";
const AGENT_REGISTER_ANCHOR='return baseImotionMonitor.registerImotionMonitorRoutes(app,{...deps,runSSH:wrappedRunSSH});';
const REGISTRY_IMPORT_ANCHOR="import { registerHostActionsV2Plugin } from '../plugins/hostActionsV2.js';";
const REGISTRY_REGISTER_ANCHOR='  registerHostActionsV2Plugin(mcp, context);';

function fail(code){throw new Error(code);}
function sha(bytes){return crypto.createHash('sha256').update(bytes).digest('hex');}
function safeRegular(file){const st=fs.lstatSync(file);return st.isFile()&&!st.isSymbolicLink();}
function readBytes(file){if(!fs.existsSync(file)||!safeRegular(file))fail('unsafe_file:'+file);return fs.readFileSync(file);}
function readText(file){return readBytes(file).toString('utf8');}
function count(source,needle){return source.split(needle).length-1;}
function replaceOnce(source,needle,replacement,label){const n=count(source,needle);if(n!==1)fail(label+'_anchor_count_'+n);return source.replace(needle,replacement);}
function assertSha(label,file,expected){const actual=sha(readBytes(file));if(actual!==expected)fail('sha_mismatch:'+label+':'+actual);return actual;}
function embedded(label,b64,expected){const bytes=Buffer.from(b64,'base64');if(sha(bytes)!==expected)fail('embedded_'+label+'_sha_mismatch');return bytes;}

function patchAgentServer(source){
  if(source.includes('honartikIticketV14PreflightRoutes')||source.includes('registerHonartikIticketV14PreflightRoutes'))fail('agent_preflight_already_patched');
  let out=replaceOnce(source,AGENT_IMPORT_ANCHOR,AGENT_IMPORT_ANCHOR+"\nconst { registerHonartikIticketV14PreflightRoutes } = require('./honartikIticketV14PreflightRoutes.js');",'agent_preflight_import');
  const registration=[
    'const imotionRegistration=baseImotionMonitor.registerImotionMonitorRoutes(app,{...deps,runSSH:wrappedRunSSH});',
    "registerHonartikIticketV14PreflightRoutes(app,{auth:deps.auth});",
    'return imotionRegistration;'
  ].join('\n');
  out=replaceOnce(out,AGENT_REGISTER_ANCHOR,registration,'agent_preflight_register');
  return out;
}
function patchRegistry(source){
  if(source.includes('registerHonartikIticketPreflightPlugin')||source.includes("../plugins/honartikIticketPreflight.js"))fail('mcp_registry_preflight_already_patched');
  let out=replaceOnce(source,REGISTRY_IMPORT_ANCHOR,REGISTRY_IMPORT_ANCHOR+"\nimport { registerHonartikIticketPreflightPlugin } from '../plugins/honartikIticketPreflight.js';",'mcp_registry_import');
  out=replaceOnce(out,REGISTRY_REGISTER_ANCHOR,REGISTRY_REGISTER_ANCHOR+'\n  registerHonartikIticketPreflightPlugin(mcp, context);','mcp_registry_register');
  return out;
}
function nodeCheckSource(label,source,esm=false){
  const args=esm?['--input-type=module','--check']:['--check'];
  const r=cp.spawnSync('/usr/local/bin/prhm-node',args,{input:source,encoding:'utf8',timeout:30000,maxBuffer:1024*1024,stdio:['pipe','pipe','pipe']});
  if(r.error||r.status!==0)fail('node_check_failed:'+label+':'+String(r.stderr||r.error?.message||'').slice(0,300));return true;
}
function validatePlugin(source){
  if(!source.includes("mcp.registerTool(TOOL")||!source.includes('inputSchema:{},annotations:RO'))fail('mcp_plugin_contract_invalid');
  if(!source.includes("agent.callAgent('/honartik/iticket/v14/preflight','POST',{})"))fail('mcp_plugin_agent_route_invalid');
  if(source.includes('host_action_v2_apply')||source.includes('host_action_v2_request')||source.includes('honartik_iticket_dark_backend_batch1_v1'))fail('mcp_plugin_mutation_surface');
  return true;
}
function validateRegistry(source){
  if(count(source,"import { registerHonartikIticketPreflightPlugin } from '../plugins/honartikIticketPreflight.js';")!==1)fail('mcp_registry_import_invalid');
  if(count(source,'registerHonartikIticketPreflightPlugin(mcp, context);')!==1)fail('mcp_registry_register_invalid');
  return true;
}
function prepare(){
  if(os.hostname()!=='prhm-production.prhm.ir')fail('wrong_host:'+os.hostname());
  if(fs.existsSync(PATHS.marker))return {alreadyInstalled:true,marker:verifyInstalledMarker()};
  assertSha('agentServer',PATHS.agentServer,EXPECTED.agentServer);
  assertSha('registry',PATHS.mcpRegistry,EXPECTED.registry);
  assertSha('hostActionsV2',PATHS.hostActionsV2,IMMUTABLE_HOST_ACTIONS_V2_SHA);
  for(const file of [PATHS.agentRoute,PATHS.mcpPlugin,PATHS.payload])if(fs.existsSync(file))fail('target_new_file_already_exists:'+file);
  const route=embedded('route',ROUTE_B64,ROUTE_SHA),payload=embedded('v14',V14_B64,V14_SHA),mcpPlugin=embedded('mcp_plugin',MCP_PLUGIN_B64,MCP_PLUGIN_SHA);
  const agentSource=readText(PATHS.agentServer);
  const registrySource=readText(PATHS.mcpRegistry);
  const patched={agentServer:patchAgentServer(agentSource),registry:patchRegistry(registrySource)};
  nodeCheckSource('agentServer',patched.agentServer);nodeCheckSource('mcpRegistry',patched.registry,true);nodeCheckSource('agentRoute',route.toString('utf8'));nodeCheckSource('mcpPlugin',mcpPlugin.toString('utf8'),true);nodeCheckSource('payload',payload.toString('utf8'));
  validateRegistry(patched.registry);validatePlugin(mcpPlugin.toString('utf8'));
  return {alreadyInstalled:false,route,payload,mcpPlugin,patched};
}
function reportPrepared(prepared){
  if(prepared.alreadyInstalled)return {ok:true,schema_version:'prhm.readonly-adapter-install-preflight.v1',version:VERSION,tool:TOOL,preflight_only:true,already_installed:true,baseline_match:null,payload_sha256:V14_SHA,route_sha256:ROUTE_SHA,mcp_plugin_sha256:MCP_PLUGIN_SHA,host_actions_v2_sha256:IMMUTABLE_HOST_ACTIONS_V2_SHA,control_plane_mutation:false,production_mutation:false,database_mutation:false,deploy:false,external_network:false,token_read:false};
  return {ok:true,schema_version:'prhm.readonly-adapter-install-preflight.v1',version:VERSION,tool:TOOL,preflight_only:true,already_installed:false,baseline_match:true,payload_sha256:V14_SHA,route_sha256:ROUTE_SHA,mcp_plugin_sha256:MCP_PLUGIN_SHA,host_actions_v2_sha256:IMMUTABLE_HOST_ACTIONS_V2_SHA,current_hashes:EXPECTED,candidate_hashes:{agentServer:sha(Buffer.from(prepared.patched.agentServer)),registry:sha(Buffer.from(prepared.patched.registry))},control_plane_mutation:false,production_mutation:false,database_mutation:false,deploy:false,external_network:false,token_read:false};
}
function preflight(){return reportPrepared(prepare());}
function atomicWrite(file,bytes,mode,uid,gid){fs.mkdirSync(path.dirname(file),{recursive:true,mode:0o755});const tmp=file+'.v14-1-'+process.pid+'-'+Date.now()+'.tmp';const fd=fs.openSync(tmp,'wx',mode);try{fs.writeFileSync(fd,bytes);fs.fsyncSync(fd);}finally{fs.closeSync(fd);}fs.chmodSync(tmp,mode);if(Number.isInteger(uid)&&Number.isInteger(gid))fs.chownSync(tmp,uid,gid);fs.renameSync(tmp,file);}
function backupFile(file,dir,label){const st=fs.statSync(file);const target=path.join(dir,label+'.bak');fs.copyFileSync(file,target,fs.constants.COPYFILE_EXCL);fs.chmodSync(target,0o600);return {file,target,mode:st.mode&0o777,uid:st.uid,gid:st.gid};}
function restoreBackup(state){atomicWrite(state.file,fs.readFileSync(state.target),state.mode,state.uid,state.gid);}
function systemctl(...args){return cp.execFileSync('/usr/bin/systemctl',args,{encoding:'utf8',stdio:['ignore','pipe','pipe'],timeout:90000}).trim();}
function httpHealth(port){return new Promise(resolve=>{const req=http.request({host:'127.0.0.1',port,path:'/health',method:'GET'},res=>{let size=0;const chunks=[];res.on('data',c=>{size+=c.length;if(size<=65536)chunks.push(c);});res.on('end',()=>{if(res.statusCode!==200||size>65536)return resolve(false);try{resolve(JSON.parse(Buffer.concat(chunks).toString('utf8')).ok===true);}catch{resolve(false);}});});req.setTimeout(2000,()=>{req.destroy();resolve(false);});req.on('error',()=>resolve(false));req.end();});}
async function waitFor(fn,label){for(let i=0;i<30;i++){if(await fn())return true;await new Promise(r=>setTimeout(r,500));}fail('health_timeout:'+label);}
async function verifyHealth(){for(const s of SERVICES)if(systemctl('is-active',s)!=='active')fail('service_not_active:'+s);await waitFor(()=>httpHealth(8099),'agent-api');await waitFor(()=>httpHealth(8123),'mcp');return true;}
function installedHashes(){return {agentServer:sha(readBytes(PATHS.agentServer)),registry:sha(readBytes(PATHS.mcpRegistry)),agentRoute:sha(readBytes(PATHS.agentRoute)),mcpPlugin:sha(readBytes(PATHS.mcpPlugin)),payload:sha(readBytes(PATHS.payload)),hostActionsV2:sha(readBytes(PATHS.hostActionsV2))};}
function verifyInstalledMarker(){
  const marker=JSON.parse(readText(PATHS.marker));if(marker.schema_version!=='prhm.readonly-adapter-install.v1'||marker.version!==VERSION||marker.tool!==TOOL)fail('installed_marker_invalid');
  const actual=installedHashes();for(const [key,value] of Object.entries(actual))if(marker.installed_sha256?.[key]!==value)fail('installed_marker_sha_mismatch:'+key);
  if(actual.agentRoute!==ROUTE_SHA||actual.mcpPlugin!==MCP_PLUGIN_SHA||actual.payload!==V14_SHA||actual.hostActionsV2!==IMMUTABLE_HOST_ACTIONS_V2_SHA)fail('installed_payload_binding_invalid');
  validateRegistry(readText(PATHS.mcpRegistry));validatePlugin(readText(PATHS.mcpPlugin));if(!readText(PATHS.agentServer).includes('iticket_v14_preflight_import'))fail('installed_agent_binding_missing');return marker;
}
async function install(){
  const prepared=prepare();if(prepared.alreadyInstalled)return reportPrepared(prepared);
  const stamp=new Date().toISOString().replace(/[-:.TZ]/g,'').slice(0,14)+'-'+crypto.randomBytes(4).toString('hex');
  const backupDir='/var/backups/prhm-host-actions-v14-1-iticket-preflight-'+stamp;fs.mkdirSync(backupDir,{recursive:false,mode:0o700});
  const agentStat=fs.statSync(PATHS.agentServer),registryStat=fs.statSync(PATHS.mcpRegistry);
  const backups=[backupFile(PATHS.agentServer,backupDir,'agentServer'),backupFile(PATHS.mcpRegistry,backupDir,'registry')];
  let mutated=false;
  try{
    mutated=true;
    atomicWrite(PATHS.agentRoute,prepared.route,0o644,agentStat.uid,agentStat.gid);
    atomicWrite(PATHS.mcpPlugin,prepared.mcpPlugin,0o644,registryStat.uid,registryStat.gid);
    atomicWrite(PATHS.payload,prepared.payload,0o644,0,0);
    atomicWrite(PATHS.agentServer,Buffer.from(prepared.patched.agentServer),agentStat.mode&0o777,agentStat.uid,agentStat.gid);
    atomicWrite(PATHS.mcpRegistry,Buffer.from(prepared.patched.registry),registryStat.mode&0o777,registryStat.uid,registryStat.gid);
    assertSha('hostActionsV2_after_write',PATHS.hostActionsV2,IMMUTABLE_HOST_ACTIONS_V2_SHA);
    for(const s of SERVICES)systemctl('restart',s);await verifyHealth();
    const hashes=installedHashes();if(hashes.agentRoute!==ROUTE_SHA||hashes.mcpPlugin!==MCP_PLUGIN_SHA||hashes.payload!==V14_SHA||hashes.hostActionsV2!==IMMUTABLE_HOST_ACTIONS_V2_SHA)fail('installed_payload_hash_invalid');validateRegistry(readText(PATHS.mcpRegistry));validatePlugin(readText(PATHS.mcpPlugin));
    const marker={schema_version:'prhm.readonly-adapter-install.v1',version:VERSION,tool:TOOL,installed_at:new Date().toISOString(),backup_dir:backupDir,installed_sha256:hashes,control_plane_mutation:true,production_application_tree_mutation:false,database_mutation:false,deploy:false,external_network:false,token_read:false,rollback_performed:false};
    atomicWrite(PATHS.marker,Buffer.from(JSON.stringify(marker,null,2)+'\n'),0o600,0,0);return {ok:true,...marker};
  }catch(error){
    const failures=[];if(mutated)for(const state of backups.slice().reverse())try{restoreBackup(state)}catch(e){failures.push(state.file+':'+e.message)}
    for(const file of [PATHS.agentRoute,PATHS.mcpPlugin,PATHS.payload])try{fs.unlinkSync(file)}catch(e){if(e.code!=='ENOENT')failures.push(file+':'+e.message)}
    for(const s of SERVICES)try{systemctl('restart',s)}catch(e){failures.push(s+':'+e.message)}
    if(failures.length)fail('install_failed_and_rollback_failed:'+failures.join('|'));fail('install_failed_rolled_back:'+String(error.message||error));
  }
}
async function main(){const result=process.argv.includes('--preflight-only')?preflight():await install();process.stdout.write(JSON.stringify(result)+'\n');}
if(require.main===module)main().catch(error=>{process.stderr.write(String(error?.stack||error)+'\n');process.exitCode=1;});
module.exports={VERSION,TOOL,V14_SHA,ROUTE_SHA,MCP_PLUGIN_SHA,IMMUTABLE_HOST_ACTIONS_V2_SHA,PATHS,EXPECTED,V14_B64,ROUTE_B64,MCP_PLUGIN_B64,patchAgentServer,patchRegistry,preflight,install};
